import React, { type CSSProperties } from 'react';
import { Button as ChakraButton, IconButton, chakra, useStyleConfig, type SystemStyleObject } from '@chakra-ui/react';
import { ZimmIcon } from '../zimmIcon';
import type { ZimmIconType, ZimmIconSize } from '../zimmIcon';

// All hover/press/focus/disabled interaction states live in zimmButton.css.ts, co-located
// beside this file. ZimmButton is a thin mapping layer: Zimmermann props (inverse,
// large/medium) → Chakra variant/size names that zimmButton.css.ts recognises.

type ZimmButtonBaseProps = {
  /** Visible label (primary/secondary) or aria-label (icon variant — no visible text). */
  label: string;
  type?: 'button' | 'submit' | 'reset';
  disabled?: boolean;
  /**
   * Renders the disabled *appearance* while keeping the button focusable and in the Tab
   * order (A10) — HTML `disabled` removes it from the accessibility tree entirely, so screen
   * reader users can never reach it to hear why the action is unavailable. `onClick` is
   * suppressed here rather than by the DOM. Prefer this over `disabled` for
   * unavailable-but-explainable states (e.g. Add to Bag with an out-of-stock size selected).
   *
   * No recipe change is needed: Chakra's `_disabled` pseudo already expands to
   * `&:disabled, &[disabled], &[aria-disabled=true], &[data-disabled]`.
   */
  ariaDisabled?: boolean;
  inverse?: boolean;
  onClick?: () => void;
  style?: CSSProperties;
  /** Chakra `sx` passthrough — for a caller-owned recipe part, not a one-off inline style. */
  sx?: SystemStyleObject;
  /**
   * Accessible name, when it has to differ from the visible `label`. Defaults to `label`.
   * For a control whose visible text is only meaningful with context — e.g. a size filter
   * chip reading "0" that should announce "Add filter: 0" — pass the full phrase here and
   * keep `label` as the short visible text.
   */
  ariaLabel?: string;
};

type ZimmLabelButtonProps = ZimmButtonBaseProps & {
  variant?: 'primary' | 'secondary';
  /** 'large' = 52px fixed · 'medium' = 40px fixed · 'adaptive' = 40px mobile → 52px desktop
   *  (same responsive size as the social variant, applied to primary/secondary colours). */
  size?: 'large' | 'medium' | 'adaptive';
  fullWidth?: boolean;
  /** Links an explanatory message element by id so screen readers announce it on focus. */
  ariaDescribedBy?: string;
  /** Optional icon rendered before the label. Pass a ZimmIcon or any React node. */
  iconLeading?: React.ReactNode;
  /** Optional icon rendered after the label. Pass a ZimmIcon or any React node. */
  iconTrailing?: React.ReactNode;
} & ({ role?: never; ariaChecked?: never } | { role: 'checkbox' | 'radio'; ariaChecked: boolean }); // `aria-checked` is a selectable control that never exposes what it is set to. // union so the role and its state cannot be supplied apart: a `role="checkbox"` with no // button and never conveys whether it is currently applied. Modelled as a discriminated // — e.g. a filter chip. Without these a screen reader announces the control as a plain // Toggle semantics, for a button that represents a *selectable state* rather than an action

type ZimmIconButtonProps = ZimmButtonBaseProps & {
  variant: 'icon';
  icon: ZimmIconType;
  /** Icon render size — one of the iconSizes keys ('sm' | 'md' | 'lg'). Defaults to 'md' (16px). */
  size?: ZimmIconSize;
};

type ZimmSocialButtonProps = ZimmButtonBaseProps & {
  variant: 'social';
  /** Icon node rendered to the left of the label (e.g. a brand logo SVG). */
  icon: React.ReactNode;
  /** Constrains the icon box to one of the four registered icon sizes. Defaults to 'md' (16px). */
  iconSize?: ZimmIconSize;
  /**
   * Inline style overrides for the icon box — use when the required size falls outside the
   * four registered `iconSize` steps (e.g. a 24 × 24 brand logo). Merged on top of the
   * `iconSize`-derived defaults, so it wins on specificity.
   */
  iconSx?: React.CSSProperties;
  /** Social buttons default to full width. Pass `false` to opt out. */
  fullWidth?: boolean;
};

export type ZimmButtonProps = ZimmLabelButtonProps | ZimmIconButtonProps | ZimmSocialButtonProps;

const ICON_SIZE_DEFAULT: ZimmIconSize = 'md';

/** Atom — labelled button (primary/secondary) or icon-only button. All visual states
 *  are handled by `zimmButton.css.ts` (co-located beside this file) — no React state for hover/press/focus.
 *  Labelled variants accept optional `iconLeading` and `iconTrailing` nodes rendered either
 *  side of the label; gap between icon and text is set by the button's flex gap in baseStyle. */
export const ZimmButton = (props: ZimmButtonProps) => {
  const {
    label,
    type = 'button',
    disabled = false,
    ariaDisabled = false,
    inverse = false,
    onClick,
    style,
    sx,
    ariaLabel,
  } = props;
  // aria-disabled leaves the button clickable at the DOM level, so the no-op has to happen here.
  const handleClick = ariaDisabled ? undefined : onClick;
  const ariaDisabledAttr = ariaDisabled || undefined;
  const labelStyle = useStyleConfig('ZimmButtonLabel', {});

  if (props.variant === 'icon') {
    return (
      <IconButton
        aria-label={ariaLabel ?? label}
        type={ariaDisabled ? 'button' : type}
        isDisabled={disabled}
        aria-disabled={ariaDisabledAttr}
        onClick={handleClick}
        variant={inverse ? 'iconInverse' : 'icon'}
        size="icon"
        icon={<ZimmIcon type={props.icon} size={props.size ?? ICON_SIZE_DEFAULT} aria-hidden={true} />}
        style={style}
        sx={sx}
      />
    );
  }

  if (props.variant === 'social') {
    const iconSizeToken = props.iconSize ?? ICON_SIZE_DEFAULT;
    // Plain <span> (not chakra.span) so aria-hidden="true" is a guaranteed DOM attribute that
    // querySelector can find. chakra.span does not reliably forward aria-* to the DOM element
    // in jsdom (the styled-system prop handling swallows it). Styles are also applied inline
    // so toHaveStyle() resolves them without needing the Emotion CSS runtime.
    const iconBoxStyle: React.CSSProperties = {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      flexShrink: 0,
      width: `var(--zimm-icon-size-${iconSizeToken})`,
      height: `var(--zimm-icon-size-${iconSizeToken})`,
      ...props.iconSx,
    };
    // Width as inline style for the same reason — Chakra's width prop becomes a CSS class that
    // getComputedStyle doesn't resolve in jsdom; inline style is always queryable by toHaveStyle.
    const buttonStyle: React.CSSProperties = {
      ...(props.fullWidth !== false ? { width: '100%' } : {}),
      ...style,
    };
    return (
      <ChakraButton
        type={ariaDisabled ? 'button' : type}
        isDisabled={disabled}
        aria-disabled={ariaDisabledAttr}
        aria-label={ariaLabel ?? label}
        onClick={handleClick}
        variant="social"
        size="social"
        style={buttonStyle}
        sx={sx}
      >
        <span aria-hidden="true" style={iconBoxStyle}>
          {props.icon}
        </span>
        <chakra.span __css={labelStyle}>{label}</chakra.span>
      </ChakraButton>
    );
  }

  const variant = props.variant ?? 'primary';
  // adaptive → reuses the 'social' Chakra size entry (same responsive height/padding tokens).
  const size = props.size === 'adaptive' ? 'social' : props.size === 'medium' ? 'sm' : 'lg';
  // Maps inverse prop to the *Inverse variant suffix defined in zimmButton.css.ts.
  const chakraVariant = `${variant}${inverse ? 'Inverse' : ''}`;
  const ariaDescribedBy = 'ariaDescribedBy' in props ? props.ariaDescribedBy : undefined;
  // The props type pairs these two, so no runtime guard is needed to keep aria-checked off a
  // plain action button.
  const role = 'role' in props ? props.role : undefined;
  const ariaChecked = 'ariaChecked' in props ? props.ariaChecked : undefined;

  return (
    <ChakraButton
      type={ariaDisabled ? 'button' : type}
      isDisabled={disabled}
      aria-disabled={ariaDisabledAttr}
      // aria-label makes the accessible name explicit so VoiceOver doesn't read
      // CSS text-transform:uppercase as an acronym (e.g. "A-D-D to bag").
      aria-label={ariaLabel ?? label}
      aria-describedby={ariaDescribedBy}
      role={role}
      aria-checked={ariaChecked}
      onClick={handleClick}
      variant={chakraVariant}
      size={size}
      width={props.fullWidth ? '100%' : undefined}
      style={style}
      sx={sx}
    >
      {props.iconLeading && (
        <chakra.span aria-hidden={true} display="flex" alignItems="center" justifyContent="center" flexShrink={0}>
          {props.iconLeading}
        </chakra.span>
      )}
      <chakra.span __css={labelStyle}>{label}</chakra.span>
      {props.iconTrailing && (
        <chakra.span aria-hidden={true} display="flex" alignItems="center" justifyContent="center" flexShrink={0}>
          {props.iconTrailing}
        </chakra.span>
      )}
    </ChakraButton>
  );
};

