import React from 'react';
import { Box, SimpleGrid, Stack, Text } from '@chakra-ui/react';
import { useIntl } from 'react-intl';
import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
import { ADD_FILTER, REMOVE_FILTER } from 'app/utils/refinementValues';
import type { ShopperSearchTypes } from 'commerce-sdk-isomorphic';

type ZimmSizeFilterProps = {
  filter: { attributeId: string; values?: ShopperSearchTypes.ProductSearchRefinementValue[] };
  toggleFilter: (value: { value: string | number }, attributeId: string, selected: boolean) => void;
  selectedFilters: readonly string[];
};

/** One flat grid of size chips using the OOTB fixed 44px column width. */
const SizeChipRow = ({ filter, toggleFilter, selectedFilters }: ZimmSizeFilterProps) => {
  const intl = useIntl();

  return (
    <SimpleGrid columns={4} spacing="var(--zimm-scale-2xs)" marginTop="var(--zimm-scale-2xs)">
      {filter.values?.map((value) => {
        const isSelected = selectedFilters.some((filterValue) => filterValue == value.value);
        if (value.hitCount === 0 && !isSelected) return null;

        return (
          <ZimmButton
            key={String(value.value)}
            variant={isSelected ? 'primary' : 'secondary'}
            size="medium"
            label={value.label}
            ariaLabel={intl.formatMessage(isSelected ? REMOVE_FILTER : ADD_FILTER, { label: value.label })}
            role="checkbox"
            ariaChecked={isSelected}
            onClick={() => toggleFilter(value, filter.attributeId, isSelected)}
            sx={{
              ...(isSelected
                ? {}
                : {
                    borderColor: 'var(--zimm-color-border-secondary)',
                    _hover: { borderColor: 'var(--zimm-color-border-secondary)' },
                  }),
            }}
          />
        );
      })}
    </SimpleGrid>
  );
};

/**
 * SFCC-847 — the Size facet's chip row, plus sub-group headings (e.g. Clothing/Accessories/
 * Shoes) when SFCC returns c_size as nested groups — the same nesting
 * `flattenRefinementValues` (overrides/app/utils/refinementValues.ts) already anticipates. A
 * flat (ungrouped) c_size refinement renders as a single ungrouped row.
 *
 * Grouping depends entirely on the shape SFCC sends: the API currently returns c_size flat, so
 * the ungrouped branch is what renders today. Producing the grouped design is BM configuration
 * (nested parent values), not a front-end change.
 *
 * @param props see ZimmSizeFilterProps
 */
export const ZimmSizeFilter = ({ filter, toggleFilter, selectedFilters }: ZimmSizeFilterProps) => {
  const groups = filter.values ?? [];
  const isNested = groups.some((group) => group.values && group.values.length > 0);

  if (!isNested) {
    return <SizeChipRow filter={filter} toggleFilter={toggleFilter} selectedFilters={selectedFilters} />;
  }

  return (
    <Stack sx={{ gap: 'var(--zimm-scale-m)' }}>
      {groups.map((group) => (
        <Box key={String(group.value)}>
          {/* Sub-group heading (Clothing / Accessories / Shoes). `textStyle="body2Strong"`
              matches the design system's 14/18 medium letterSpacing entry; the earlier
              `fontStyle="italic"` was speculative and had no Figma reference (audited
              2026-09-16). */}
          <Text textStyle="body2Strong" marginBottom="var(--zimm-scale-xs)">
            {group.label}
          </Text>
          <SizeChipRow
            filter={{ attributeId: filter.attributeId, values: group.values }}
            toggleFilter={toggleFilter}
            selectedFilters={selectedFilters}
          />
        </Box>
      ))}
    </Stack>
  );
};

