import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import { ZimmSizeFilter } from './index';

// Required since the size chips render via ZimmButton, which pulls in ZimmIcon and therefore
// the base SFCC icons barrel — whose top-level `AmexSymbol.viewBox = ...` throws under Vitest
// (SVG imports resolve to path strings here). Documented in .claude/rules/testing.md; not
// fixable from a test file because the SVG transform lives in Tier 1 vitest.config.ts.
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({ ZimmIcon: () => null }));

const renderWithProviders = (children: React.ReactNode) =>
  render(
    <ChakraProvider>
      <IntlProvider locale="en">{children}</IntlProvider>
    </ChakraProvider>,
  );

describe('ZimmSizeFilter', () => {
  test('renders a single ungrouped row for a flat (non-nested) refinement', () => {
    renderWithProviders(
